export type ErrorKind = 'marker' | 'code' | 'index' | 'sync';
export class ScanError extends Error {
  constructor(public kind: ErrorKind) {
    super(kind);
  }
}
export class BitWriter {
  bytes: number[] = [];
  paddingBits = 0;
  stuffedBytes = 0;
  private buffer = 0;
  private used = 0;
  write(value: number, length: number): void {
    for (let i = length - 1; i >= 0; i--) {
      this.buffer = 2 * this.buffer + (Math.floor(value / 2 ** i) % 2);
      this.used++;
      if (this.used === 8) {
        this.bytes.push(this.buffer);
        if (this.buffer === 255) {
          this.bytes.push(0);
          this.stuffedBytes++;
        }
        this.buffer = 0;
        this.used = 0;
      }
    }
  }
  pad(): void {
    while (this.used > 0) {
      this.write(1, 1);
      this.paddingBits++;
    }
  }
  marker(value: number): void {
    this.pad();
    this.bytes.push(255, value);
  }
}
export class BitReader {
  private buffer = 0;
  private remaining = 0;
  constructor(
    private bytes: number[],
    public position: number,
  ) {}
  read(length: number): number {
    let value = 0;
    for (let i = 0; i < length; i++) {
      if (this.remaining === 0) {
        const byte = this.bytes[this.position];
        if (byte === 255) {
          if (this.bytes[this.position + 1] !== 0) throw new ScanError('marker');
          this.position += 2;
        } else this.position++;
        this.buffer = byte;
        this.remaining = 8;
      }
      this.remaining--;
      value = 2 * value + (Math.floor(this.buffer / 2 ** this.remaining) % 2);
    }
    return value;
  }
  clear(): void {
    this.buffer = 0;
    this.remaining = 0;
  }
}
export function resync(bytes: number[], position: number): number {
  for (let q = position; q + 1 < bytes.length; q++) {
    if (
      bytes[q] === 255 &&
      ((bytes[q + 1] >= 208 && bytes[q + 1] <= 215) || bytes[q + 1] === 217)
    ) {
      return q;
    }
  }
  return bytes.length - 2;
}

import type { Image, Plane } from './image_io.ts';
export interface Factors {
  h: number;
  v: number;
}
export const clamp = (v: number) => Math.min(Math.max(v, 0), 255);
export function rgb(y: number, cb: number, cr: number): number[] {
  return [
    clamp(y + Math.floor((91881 * (cr - 128) + 32768) / 65536)),
    clamp(y + Math.floor((-22554 * (cb - 128) - 46802 * (cr - 128) + 32768) / 65536)),
    clamp(y + Math.floor((116130 * (cb - 128) + 32768) / 65536)),
  ];
}
export function convert(image: Image): Plane[] {
  const planes = Array.from({ length: 3 }, () => ({
    width: image.width,
    height: image.height,
    pixels: Array<number>(image.width * image.height),
  }));
  for (let i = 0; i < image.width * image.height; i++) {
    const [r, g, b] = image.pixels.slice(3 * i, 3 * i + 3);
    planes[0].pixels[i] = Math.floor((19595 * r + 38470 * g + 7471 * b + 32768) / 65536);
    planes[1].pixels[i] = Math.floor((-11059 * r - 21709 * g + 32768 * b + 8421375) / 65536);
    planes[2].pixels[i] = Math.floor((32768 * r - 27439 * g - 5329 * b + 8421375) / 65536);
  }
  return planes;
}
export function geometry(width: number, height: number, factors: Factors[]) {
  const hmax = Math.max(...factors.map((f) => f.h));
  const vmax = Math.max(...factors.map((f) => f.v));
  const mx = Math.ceil(width / (8 * hmax));
  const my = Math.ceil(height / (8 * vmax));
  return { hmax, vmax, mx, my, pw: 8 * hmax * mx, ph: 8 * vmax * my };
}
export function componentPlanes(image: Image, factors: Factors[]): Plane[] {
  const original = convert(image);
  const g = geometry(image.width, image.height, factors);
  return factors.map((factor, c) => {
    const width = 8 * factor.h * g.mx;
    const height = 8 * factor.v * g.my;
    const fx = g.hmax / factor.h;
    const fy = g.vmax / factor.v;
    const pixels: number[] = [];
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        let sum = 0;
        for (let j = 0; j < fy; j++) {
          for (let i = 0; i < fx; i++) {
            sum +=
              original[c].pixels[
                Math.min(fy * y + j, image.height - 1) * image.width +
                  Math.min(fx * x + i, image.width - 1)
