}
export function upsample(
  planes: Plane[],
  width: number,
  height: number,
  factors: Factors[],
): Plane[] {
  const g = geometry(width, height, factors);
  return factors.map((f, c) => ({
    width,
    height,
    pixels: Array.from(
      { length: width * height },
      (_, i) =>
        planes[c].pixels[
          Math.floor((Math.floor(i / width) * f.v) / g.vmax) * planes[c].width +
            Math.floor(((i % width) * f.h) / g.hmax)
