}

import { clamp } from './color.ts';
const rnd = (a: number, s: number) => Math.floor((a + 2 ** (s - 1)) / 2 ** s);
export const zigzag = Array.from({ length: 64 }, (_, i) => i).sort((a, b) => {
  const u = Math.floor(a / 8);
  const v = a % 8;
  const x = Math.floor(b / 8);
  const y = b % 8;
  return u + v - x - y || ((u + v) % 2 ? u - x : x - u);
});
export function quantization(bases: number[][], quality: number): number[][] {
  const scale = quality < 50 ? Math.floor(5000 / quality) : 200 - 2 * quality;
  return bases.map((base) =>
    base.map((v) => Math.min(Math.max(Math.floor((v * scale + 50) / 100), 1), 255)),
  );
}
export function transform(block: number[], c: number[][]): number[] {
  const e = Array<number>(64);
  const f = Array<number>(64);
  for (let u = 0; u < 8; u++) {
    for (let x = 0; x < 8; x++) {
      let sum = 0;
      for (let y = 0; y < 8; y++) sum += c[u][y] * (block[8 * y + x] - 128);
      e[8 * u + x] = rnd(sum, 11);
    }
  }
  for (let u = 0; u < 8; u++) {
    for (let v = 0; v < 8; v++) {
      let sum = 0;
      for (let x = 0; x < 8; x++) sum += e[8 * u + x] * c[v][x];
      f[8 * u + v] = rnd(sum, 15);
    }
  }
  return f;
}
export function inverse(d: number[], c: number[][]): number[] {
  const s = Array<number>(64);
  const g = Array<number>(64);
  for (let y = 0; y < 8; y++) {
    for (let v = 0; v < 8; v++) {
      let sum = 0;
      for (let u = 0; u < 8; u++) sum += c[u][y] * d[8 * u + v];
      s[8 * y + v] = rnd(sum, 11);
    }
  }
  for (let y = 0; y < 8; y++) {
    for (let x = 0; x < 8; x++) {
      let sum = 0;
      for (let v = 0; v < 8; v++) sum += s[8 * y + v] * c[v][x];
      g[8 * y + x] = clamp(rnd(sum, 15) + 128);
    }
  }
  return g;
}
export function quantize(f: number[], q: number[]): number[] {
  return zigzag.map((i) => {
    const a = Math.floor((Math.abs(f[i]) + Math.floor(q[i] / 2)) / q[i]);
    return f[i] >= 0 ? a : -a;
  });
}
export function dequantize(z: number[], q: number[], keep = 64): number[] {
  const d = Array<number>(64).fill(0);
  zigzag.forEach((index, i) => {
    if (i < keep) d[index] = z[i] * q[index];
  });
  return d;
}

export interface HuffmanTable {
  class: number;
  id: number;
  counts: number[];
  values: number[];
}
export interface Code {
  length: number;
  value: number;
}
export function category(a: number): number {
  let n = 0;
  for (let value = Math.abs(a); value > 0; value = Math.floor(value / 2)) n++;
  return n;
}
export function extra(a: number, n: number): number {
  return a >= 0 ? a : a + 2 ** n - 1;
}
export function signed(w: number, n: number): number {
  return n === 0 ? 0 : w >= 2 ** (n - 1) ? w : w - 2 ** n + 1;
}
export function assign(table: HuffmanTable) {
  const encode = new Map<number, Code>();
  const decode = new Map<string, number>();
  let code = 0;
  let index = 0;
  for (let length = 1; length <= 16; length++) {
    for (let j = 0; j < table.counts[length - 1]; j++) {
      const symbol = table.values[index++];
      encode.set(symbol, { length, value: code });
      decode.set(`${length}:${code}`, symbol);
      code++;
    }
    code *= 2;
  }
  return { encode, decode };
}
export function optimized(frequencies: number[], tableClass: number, id: number): HuffmanTable {
  const freq = [...frequencies, 1];
  const codesize = Array<number>(257).fill(0);
  const others = Array<number>(257).fill(-1);
  while (true) {
    let c1 = -1;
    let c2 = -1;
    for (let i = 0; i <= 256; i++) if (freq[i] > 0 && (c1 < 0 || freq[i] <= freq[c1])) c1 = i;
    for (let i = 0; i <= 256; i++) {
      if (i !== c1 && freq[i] > 0 && (c2 < 0 || freq[i] <= freq[c2])) c2 = i;
    }
    if (c2 < 0) break;
    freq[c1] += freq[c2];
    freq[c2] = 0;
    codesize[c1]++;
    while (others[c1] !== -1) {
      c1 = others[c1];
      codesize[c1]++;
    }
    others[c1] = c2;
    codesize[c2]++;
    while (others[c2] !== -1) {
      c2 = others[c2];
      codesize[c2]++;
    }
  }
  const count = Array<number>(258).fill(0);
  for (const length of codesize) if (length > 0) count[length]++;
  for (let length = count.length - 1; length >= 17; length--) {
    while (count[length] > 0) {
      let j = length - 2;
      while (count[j] === 0) j--;
      count[length] -= 2;
      count[length - 1]++;
      count[j + 1] += 2;
      count[j]--;
    }
  }
  let last = 16;
  while (count[last] === 0) last--;
  count[last]--;
  const values = frequencies
    .map((_, i) => i)
    .filter((i) => codesize[i] > 0)
    .sort((a, b) => codesize[a] - codesize[b] || a - b);
  return { class: tableClass, id, counts: count.slice(1, 17), values };
}

import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import type { HuffmanTable } from './entropy.ts';
export interface Image {
  width: number;
  height: number;
  pixels: number[];
}
export interface Plane {
  width: number;
  height: number;
  pixels: number[];
}
export interface Parameters {
  qualities: number[];
