    frame.components.forEach((c, component) => {
      for (let v = 0; v < c.v; v++) {
        for (let h = 0; h < c.h; h++) {
          blocks.push({
            mcu,
            component,
            bx: c.h * (mcu % g.mx) + h,
            by: c.v * Math.floor(mcu / g.mx) + v,
